package me.kright.gametools.pga2d

import scala.annotation.targetName
import me.kright.gametools.flatarray.FlatDoubleSerializer


/**
 * A motor: a rigid transformation of the 2d plane (combined rotation and translation),
 * the even-graded (0, 2) element of 2d PGA. Applied with motor.sandwich(obj).
 * A motor is the exponent of a grade-2 element (projectivePoint.exp), and motor.log returns that element back.
 *
 * Variable fields: s, wx, wy, xy.
 *
 * Generated by pgaNdCodeGen (me.kright.gametools.pga.codegen.scalagen.pga2d.runScalaCodeGen).
 * Do not edit by hand: change the generator and re-run it.
 */
final case class Pga2dMotor(s: Double = 0.0,
                            wx: Double = 0.0,
                            wy: Double = 0.0,
                            xy: Double = 0.0) derives CanEqual, FlatDoubleSerializer:

  override def toString: String =
    s"Pga2dMotor(s = $s, wx = $wx, wy = $wy, xy = $xy)"

  def dual: Pga2dMultivector =
    Pga2dMultivector(
      s = 0.0,
      w = xy,
      x = -wy,
      y = wx,
      wx = 0.0,
      wy = 0.0,
      xy = 0.0,
      i = s,
    )

  def weight: Pga2dVector =
    Pga2dVector(
      x = -wy,
      y = wx,
    )

  def bulk: Pga2dRotor =
    Pga2dRotor(
      s = s,
      xy = xy,
    )

  @targetName("unaryMinus")
  def unary_- : Pga2dMotor =
    Pga2dMotor(
      s = -s,
      wx = -wx,
      wy = -wy,
      xy = -xy,
    )

  def reverse: Pga2dMotor =
    Pga2dMotor(
      s = s,
      wx = -wx,
      wy = -wy,
      xy = -xy,
    )

  def antiReverse: Pga2dMotor =
    Pga2dMotor(
      s = -s,
      wx = wx,
      wy = wy,
      xy = xy,
    )

  /**
   * 2D motors satisfy m * reverse(m) = scalar exactly, so renormalization is a uniform scale
   */
  def renormalized: Pga2dMotor =
    val a = 1.0 / Math.sqrt(s * s + xy * xy)
    Pga2dMotor(
      s = a * s,
      wx = a * wx,
      wy = a * wy,
      xy = a * xy,
    )

  /** motor has to be normalized */
  def toRotorAndTranslator: (Pga2dRotor, Pga2dTranslator) = {
    val q = this.toRotorUnsafe
    val t = q.reverse.geometric(this)
    (q, t.toTranslatorUnsafe)
  }

  /** motor has to be normalized */
  def toTranslatorAndRotor: (Pga2dTranslator, Pga2dRotor) = {
    val q = this.toRotorUnsafe
    val t = this.geometric(q.reverse)
    (t.toTranslatorUnsafe, q)
  }

  def bulkNormSquare: Double =
    (s * s + xy * xy)

  def bulkNorm: Double =
    Math.sqrt(bulkNormSquare)

  def normalizedByBulk =
    this / bulkNorm

  def weightNormSquare: Double =
    (wx * wx + wy * wy)

  def weightNorm: Double =
    Math.sqrt(weightNormSquare)

  def normalizedByWeight =
    this / weightNorm

  def normSquare: Double =
    (s * s + wx * wx + wy * wy + xy * xy)

  def norm: Double =
    Math.sqrt(normSquare)

  def normalizedByNorm =
    this / norm

  @targetName("times")
  def *(r: Double): Pga2dMotor =
    Pga2dMotor(
      s = r * s,
      wx = r * wx,
      wy = r * wy,
      xy = r * xy,
    )

  /** multiplies by the reciprocal: one division instead of one per component, at the cost of one extra rounding (~0.5 ulp) */
  @targetName("div")
  def /(r: Double): Pga2dMotor =
    this * (1.0 / r)

  @targetName("plus")
  def +(r: Pga2dMotor): Pga2dMotor =
    Pga2dMotor(
      s = (r.s + s),
      wx = (r.wx + wx),
      wy = (r.wy + wy),
      xy = (r.xy + xy),
    )

  @targetName("minus")
  def -(r: Pga2dMotor): Pga2dMotor =
    Pga2dMotor(
      s = (s - r.s),
      wx = (wx - r.wx),
      wy = (wy - r.wy),
      xy = (xy - r.xy),
    )

  def madd(r: Pga2dMotor, mult: Double): Pga2dMotor =
    Pga2dMotor(
      s = (s + mult * r.s),
      wx = (wx + mult * r.wx),
      wy = (wy + mult * r.wy),
      xy = (xy + mult * r.xy),
    )

  /** componentwise product on the raw fields; NOT a geometric-algebra operation (basis-dependent) */
  def scale(r: Pga2dMotor): Pga2dMotor =
    Pga2dMotor(
      s = s * r.s,
      wx = wx * r.wx,
      wy = wy * r.wy,
      xy = xy * r.xy,
    )

  /** componentwise 1/x on the raw fields (a zero field yields Infinity); NOT the multiplicative inverse */
  def reciprocal: Pga2dMotor =
    Pga2dMotor(
      s = 1.0 / s,
      wx = 1.0 / wx,
      wy = 1.0 / wy,
      xy = 1.0 / xy,
    )

  def log: Pga2dProjectivePoint =
    val scalar = s
    if (s < 0.0) return (-this).log

    val lenXY = Math.abs(xy)
    val angle = Math.atan2(lenXY, scalar)

    // for a normalized motor sin(angle) = lenXY, so this is angle / sin(angle);
    // dividing by lenXY directly avoids the catastrophic cancellation that the
    // equivalent sqrt(1.0 - scalar * scalar) form has for small angles
    val b = if (Math.abs(angle) > 1e-5) {
      angle / lenXY
    } else {
      // x/sin(x) = 1 / (sin(x)/x) = 1 / (1 - x^2/6 + x^4/120 - ...);
      // substitute v = x^2/6 - x^4/120 + ... into 1/(1 - v) = 1 + v + v^2 + ...:
      //   x/sin(x) = 1 + x^2/6 + (1/36 - 1/120)*x^4 + ...
      //            = 1 + x^2/6 + 7*x^4/360 + ...
      // at x <= 1e-5 the dropped 7*x^4/360 <= 2e-22 relative term is far below 1e-17,
      // so the second-order form is exact in double
      1.0 + angle * angle / 6.0
    }

    Pga2dProjectivePoint(
      x = -b * wy,
      y = b * wx,
      w = b * xy,
    )

  /**
   * Spherical linear interpolation along the geodesic from this (t = 0) to b (t = 1),
   * with constant angular velocity. Computes this * (this.reverse.geometric(b))^t via log/exp.
   * Assumes both this and b are normalized; the result is normalized.
   * Near-antipodal inputs (b close to -this) are ill-conditioned: the geodesic is undefined
   * there and the interpolation direction becomes numerically unstable.
   */
  def slerp(b: Pga2dMotor, t: Double): Pga2dMotor =
    this.geometric(this.reverse.geometric(b).log.exp(t))

  /**
   * Normalized linear interpolation: the componentwise lerp this * (1 - t) + b * t, renormalized.
   * A fast APPROXIMATION of slerp: the angular velocity is not constant, so intermediate values
   * deviate from the true geodesic. The error is negligible for small angles between this and b
   * and grows toward the midpoint of large rotations. Assumes both inputs are normalized.
   */
  def nlerp(b: Pga2dMotor, t: Double): Pga2dMotor =
    (this * (1.0 - t) + b * t).renormalized

  def toMultivector: Pga2dMultivector =
    Pga2dMultivector(
      s = s,
      w = 0.0,
      x = 0.0,
      y = 0.0,
      wx = wx,
      wy = wy,
      xy = xy,
      i = 0.0,
    )

  def toProjectivePointUnsafe: Pga2dProjectivePoint =
    Pga2dProjectivePoint(
      x = -wy,
      y = wx,
      w = xy,
    )

  def toRotorUnsafe: Pga2dRotor =
    Pga2dRotor(
      s = s,
      xy = xy,
    )

  def toProjectiveTranslatorUnsafe: Pga2dProjectiveTranslator =
    Pga2dProjectiveTranslator(
      s = s,
      wx = wx,
      wy = wy,
    )

  def toTranslatorUnsafe: Pga2dTranslator =
    Pga2dTranslator(
      wx = wx,
      wy = wy,
    )

  def toVectorUnsafe: Pga2dVector =
    Pga2dVector(
      x = -wy,
      y = wx,
    )

  def toPointUnsafe: Pga2dPoint =
    Pga2dPoint(
      x = -wy,
      y = wx,
    )

  def axisX: Pga2dVector =
    toRotorUnsafe.axisX

  def axisY: Pga2dVector =
    toRotorUnsafe.axisY

  infix def geometric(r: Pga2dMotor): Pga2dMotor =
    Pga2dMotor(
      s = (r.s * s - r.xy * xy),
      wx = (r.s * wx + r.wx * s + r.wy * xy - r.xy * wy),
      wy = (r.s * wy + r.wy * s + r.xy * wx - r.wx * xy),
      xy = (r.s * xy + r.xy * s),
    )

  infix def geometric(r: Pga2dLine): Pga2dMultivector =
    Pga2dMultivector(
      s = 0.0,
      w = (r.w * s + r.x * wx + r.y * wy),
      x = (r.x * s + r.y * xy),
      y = (r.y * s - r.x * xy),
      wx = 0.0,
      wy = 0.0,
      xy = 0.0,
      i = (r.w * xy + r.y * wx - r.x * wy),
    )

  infix def geometric(r: Pga2dProjectivePoint): Pga2dMotor =
    Pga2dMotor(
      s = -r.w * xy,
      wx = (r.y * s - r.w * wy - r.x * xy),
      wy = (r.w * wx - r.x * s - r.y * xy),
      xy = r.w * s,
    )

  infix def geometric(r: Pga2dRotor): Pga2dMotor =
    Pga2dMotor(
      s = (r.s * s - r.xy * xy),
      wx = (r.s * wx - r.xy * wy),
      wy = (r.s * wy + r.xy * wx),
      xy = (r.s * xy + r.xy * s),
    )

  infix def geometric(r: Pga2dProjectiveTranslator): Pga2dMotor =
    Pga2dMotor(
      s = r.s * s,
      wx = (r.s * wx + r.wx * s + r.wy * xy),
      wy = (r.s * wy + r.wy * s - r.wx * xy),
      xy = r.s * xy,
    )

  infix def geometric(r: Pga2dTranslator): Pga2dMotor =
    Pga2dMotor(
      s = s,
      wx = (wx + r.wx * s + r.wy * xy),
      wy = (wy + r.wy * s - r.wx * xy),
      xy = xy,
    )

  infix def geometric(r: Pga2dVector): Pga2dVector =
    Pga2dVector(
      x = (r.x * s + r.y * xy),
      y = (r.y * s - r.x * xy),
    )

  infix def geometric(r: Pga2dPoint): Pga2dMotor =
    Pga2dMotor(
      s = -xy,
      wx = (-wy + r.y * s - r.x * xy),
      wy = (wx - r.x * s - r.y * xy),
      xy = s,
    )

  infix def geometric(r: Pga2dLineCentral): Pga2dMultivector =
    Pga2dMultivector(
      s = 0.0,
      w = (r.x * wx + r.y * wy),
      x = (r.x * s + r.y * xy),
      y = (r.y * s - r.x * xy),
      wx = 0.0,
      wy = 0.0,
      xy = 0.0,
      i = (r.y * wx - r.x * wy),
    )

  infix def geometric(r: Pga2dPseudoScalar): Pga2dMultivector =
    Pga2dMultivector(
      s = 0.0,
      w = -r.i * xy,
      x = 0.0,
      y = 0.0,
      wx = 0.0,
      wy = 0.0,
      xy = 0.0,
      i = r.i * s,
    )

  infix def geometric(r: Pga2dPointCenter.type): Pga2dMotor =
    Pga2dMotor(
      s = -xy,
      wx = -wy,
      wy = wx,
      xy = s,
    )

  infix def dot(r: Pga2dMotor): Pga2dMotor =
    Pga2dMotor(
      s = (r.s * s - r.xy * xy),
      wx = (r.s * wx + r.wx * s),
      wy = (r.s * wy + r.wy * s),
      xy = (r.s * xy + r.xy * s),
    )

  infix def dot(r: Pga2dLine): Pga2dLine =
    Pga2dLine(
      x = (r.x * s + r.y * xy),
      y = (r.y * s - r.x * xy),
      w = (r.w * s + r.x * wx + r.y * wy),
    )

  infix def dot(r: Pga2dProjectivePoint): Pga2dMotor =
    Pga2dMotor(
      s = -r.w * xy,
      wx = r.y * s,
      wy = -r.x * s,
      xy = r.w * s,
    )

  infix def dot(r: Pga2dRotor): Pga2dMotor =
    Pga2dMotor(
      s = (r.s * s - r.xy * xy),
      wx = r.s * wx,
      wy = r.s * wy,
      xy = (r.s * xy + r.xy * s),
    )

  infix def dot(r: Pga2dProjectiveTranslator): Pga2dMotor =
    Pga2dMotor(
      s = r.s * s,
      wx = (r.s * wx + r.wx * s),
      wy = (r.s * wy + r.wy * s),
      xy = r.s * xy,
    )

  infix def dot(r: Pga2dTranslator): Pga2dMotor =
    Pga2dMotor(
      s = s,
      wx = (wx + r.wx * s),
      wy = (wy + r.wy * s),
      xy = xy,
    )

  infix def dot(r: Pga2dVector): Pga2dVector =
    Pga2dVector(
      x = r.x * s,
      y = r.y * s,
    )

  infix def dot(r: Pga2dPoint): Pga2dMotor =
    Pga2dMotor(
      s = -xy,
      wx = r.y * s,
      wy = -r.x * s,
      xy = s,
    )

  infix def dot(r: Pga2dLineCentral): Pga2dLine =
    Pga2dLine(
      x = (r.x * s + r.y * xy),
      y = (r.y * s - r.x * xy),
      w = (r.x * wx + r.y * wy),
    )

  infix def dot(r: Pga2dPseudoScalar): Pga2dMultivector =
    Pga2dMultivector(
      s = 0.0,
      w = -r.i * xy,
      x = 0.0,
      y = 0.0,
      wx = 0.0,
      wy = 0.0,
      xy = 0.0,
      i = r.i * s,
    )

  infix def dot(r: Pga2dPointCenter.type): Pga2dRotor =
    Pga2dRotor(
      s = -xy,
      xy = s,
    )

  infix def wedge(r: Pga2dMotor): Pga2dMotor =
    Pga2dMotor(
      s = r.s * s,
      wx = (r.s * wx + r.wx * s),
      wy = (r.s * wy + r.wy * s),
      xy = (r.s * xy + r.xy * s),
    )

  inline infix def ^(r: Pga2dMotor): Pga2dMotor = wedge(r)

  inline infix def meet(r: Pga2dMotor): Pga2dMotor = wedge(r)

  infix def wedge(r: Pga2dLine): Pga2dMultivector =
    Pga2dMultivector(
      s = 0.0,
      w = r.w * s,
      x = r.x * s,
      y = r.y * s,
      wx = 0.0,
      wy = 0.0,
      xy = 0.0,
      i = (r.w * xy + r.y * wx - r.x * wy),
    )

  inline infix def ^(r: Pga2dLine): Pga2dMultivector = wedge(r)

  inline infix def meet(r: Pga2dLine): Pga2dMultivector = wedge(r)

  infix def wedge(r: Pga2dProjectivePoint): Pga2dProjectivePoint =
    Pga2dProjectivePoint(
      x = r.x * s,
      y = r.y * s,
      w = r.w * s,
    )

  inline infix def ^(r: Pga2dProjectivePoint): Pga2dProjectivePoint = wedge(r)

  inline infix def meet(r: Pga2dProjectivePoint): Pga2dProjectivePoint = wedge(r)

  infix def wedge(r: Pga2dRotor): Pga2dMotor =
    Pga2dMotor(
      s = r.s * s,
      wx = r.s * wx,
      wy = r.s * wy,
      xy = (r.s * xy + r.xy * s),
    )

  inline infix def ^(r: Pga2dRotor): Pga2dMotor = wedge(r)

  inline infix def meet(r: Pga2dRotor): Pga2dMotor = wedge(r)

  infix def wedge(r: Pga2dProjectiveTranslator): Pga2dMotor =
    Pga2dMotor(
      s = r.s * s,
      wx = (r.s * wx + r.wx * s),
      wy = (r.s * wy + r.wy * s),
      xy = r.s * xy,
    )

  inline infix def ^(r: Pga2dProjectiveTranslator): Pga2dMotor = wedge(r)

  inline infix def meet(r: Pga2dProjectiveTranslator): Pga2dMotor = wedge(r)

  infix def wedge(r: Pga2dTranslator): Pga2dMotor =
    Pga2dMotor(
      s = s,
      wx = (wx + r.wx * s),
      wy = (wy + r.wy * s),
      xy = xy,
    )

  inline infix def ^(r: Pga2dTranslator): Pga2dMotor = wedge(r)

  inline infix def meet(r: Pga2dTranslator): Pga2dMotor = wedge(r)

  infix def wedge(r: Pga2dVector): Pga2dVector =
    Pga2dVector(
      x = r.x * s,
      y = r.y * s,
    )

  inline infix def ^(r: Pga2dVector): Pga2dVector = wedge(r)

  inline infix def meet(r: Pga2dVector): Pga2dVector = wedge(r)

  infix def wedge(r: Pga2dPoint): Pga2dProjectivePoint =
    Pga2dProjectivePoint(
      x = r.x * s,
      y = r.y * s,
      w = s,
    )

  inline infix def ^(r: Pga2dPoint): Pga2dProjectivePoint = wedge(r)

  inline infix def meet(r: Pga2dPoint): Pga2dProjectivePoint = wedge(r)

  infix def wedge(r: Pga2dLineCentral): Pga2dMultivector =
    Pga2dMultivector(
      s = 0.0,
      w = 0.0,
      x = r.x * s,
      y = r.y * s,
      wx = 0.0,
      wy = 0.0,
      xy = 0.0,
      i = (r.y * wx - r.x * wy),
    )

  inline infix def ^(r: Pga2dLineCentral): Pga2dMultivector = wedge(r)

  inline infix def meet(r: Pga2dLineCentral): Pga2dMultivector = wedge(r)

  infix def wedge(r: Pga2dPseudoScalar): Pga2dPseudoScalar =
    Pga2dPseudoScalar(
      i = r.i * s,
    )

  inline infix def ^(r: Pga2dPseudoScalar): Pga2dPseudoScalar = wedge(r)

  inline infix def meet(r: Pga2dPseudoScalar): Pga2dPseudoScalar = wedge(r)

  infix def wedge(r: Pga2dPointCenter.type): Pga2dRotor =
    Pga2dRotor(
      s = 0.0,
      xy = s,
    )

  inline infix def ^(r: Pga2dPointCenter.type): Pga2dRotor = wedge(r)

  inline infix def meet(r: Pga2dPointCenter.type): Pga2dRotor = wedge(r)

  infix def antiGeometric(r: Pga2dMotor): Pga2dMultivector =
    Pga2dMultivector(
      s = 0.0,
      w = (r.wy * wx - r.wx * wy),
      x = (r.xy * wx - r.s * wy - r.wx * xy - r.wy * s),
      y = (r.s * wx + r.wx * s + r.xy * wy - r.wy * xy),
      wx = 0.0,
      wy = 0.0,
      xy = 0.0,
      i = (r.wx * wx + r.wy * wy),
    )

  infix def antiGeometric(r: Pga2dLine): Pga2dMotor =
    Pga2dMotor(
      s = (r.w * xy + r.y * wx - r.x * wy),
      wx = -r.w * wy,
      wy = r.w * wx,
      xy = (r.x * wx + r.y * wy - r.w * s),
    )

  infix def antiGeometric(r: Pga2dProjectivePoint): Pga2dMultivector =
    Pga2dMultivector(
      s = 0.0,
      w = (-r.x * wx - r.y * wy),
      x = (r.w * wx + r.x * s - r.y * xy),
      y = (r.w * wy + r.x * xy + r.y * s),
      wx = 0.0,
      wy = 0.0,
      xy = 0.0,
      i = (r.y * wx - r.x * wy),
    )

  infix def antiGeometric(r: Pga2dRotor): Pga2dLineCentral =
    Pga2dLineCentral(
      x = (r.xy * wx - r.s * wy),
      y = (r.s * wx + r.xy * wy),
    )

  infix def antiGeometric(r: Pga2dProjectiveTranslator): Pga2dMultivector =
    Pga2dMultivector(
      s = 0.0,
      w = (r.wy * wx - r.wx * wy),
      x = (-r.s * wy - r.wx * xy - r.wy * s),
      y = (r.s * wx + r.wx * s - r.wy * xy),
      wx = 0.0,
      wy = 0.0,
      xy = 0.0,
      i = (r.wx * wx + r.wy * wy),
