  infix def antiGeometric(r: Pga2dTranslator): Pga2dMultivector =
    Pga2dMultivector(
      s = 0.0,
      w = (r.wy * wx - r.wx * wy),
      x = (-wy - r.wx * xy - r.wy * s),
      y = (wx + r.wx * s - r.wy * xy),
      wx = 0.0,
      wy = 0.0,
      xy = 0.0,
      i = (r.wx * wx + r.wy * wy),
    )

  infix def antiGeometric(r: Pga2dVector): Pga2dMultivector =
    Pga2dMultivector(
      s = 0.0,
      w = (-r.x * wx - r.y * wy),
      x = (r.x * s - r.y * xy),
      y = (r.x * xy + r.y * s),
      wx = 0.0,
      wy = 0.0,
      xy = 0.0,
      i = (r.y * wx - r.x * wy),
    )

  infix def antiGeometric(r: Pga2dPoint): Pga2dMultivector =
    Pga2dMultivector(
      s = 0.0,
      w = (-r.x * wx - r.y * wy),
      x = (wx + r.x * s - r.y * xy),
      y = (wy + r.x * xy + r.y * s),
      wx = 0.0,
      wy = 0.0,
      xy = 0.0,
      i = (r.y * wx - r.x * wy),
    )

  infix def antiGeometric(r: Pga2dLineCentral): Pga2dRotor =
    Pga2dRotor(
      s = (r.y * wx - r.x * wy),
      xy = (r.x * wx + r.y * wy),
    )

  infix def antiGeometric(r: Pga2dPseudoScalar): Pga2dMotor =
    Pga2dMotor(
      s = r.i * s,
      wx = r.i * wx,
      wy = r.i * wy,
      xy = r.i * xy,
    )

  infix def antiGeometric(r: Pga2dPointCenter.type): Pga2dLineCentral =
    Pga2dLineCentral(
      x = wx,
      y = wy,
